def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally outcomes
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    last_mine, last_opp = history[-1]

    # Consecutive runs ending at last round
    run_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_opp_d += 1
        else:
            break
    run_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_opp_c += 1
        else:
            break
    run_dd = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            run_dd += 1
        else:
            break

    opp_c = cc + dc
    coop_ratio = opp_c / float(n)
    opp_defect_after_my_c = cd
    opp_coop_after_my_d = dc

    # Opponent mirroring test: does opponent copy our previous action?
    mirror = 0
    if n >= 2:
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mirror += 1
        mirror_ratio = mirror / float(n - 1)
    else:
        mirror_ratio = 0.0

    # Extract opponent sequence
    opp = [h[1] for h in history]

    # Check for long sustained defection -> lock down
    if run_opp_d >= 6:
        if rng.random() < 0.92:
            return 'D'
        return 'C'

    # Extremely cooperative opponent
    if coop_ratio >= 0.9 and n >= 6:
        # Rare probing defeat to test, otherwise cooperate
        if n % 23 == 0 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Mostly defecting opponent
    if coop_ratio <= 0.25 and n >= 6:
        if n % 13 == 0 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # If opponent mirrors us strongly, stabilize on cooperation
    if mirror_ratio >= 0.75 and n >= 6:
        if last_mine == 'D':
            return 'C'
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    # Periodic-defector pattern detection: check for cycling defections
    periodic_hits = 0
    if n >= 10:
        for period in (2, 3, 4, 5):
            if n < period * 2:
                continue
            matches = 0
            total = 0
            for i in range(period, n):
                if opp[i] == opp[i - period]:
                    matches += 1
                total += 1
            if total and matches / float(total) > 0.9:
                # Predict next
                idx = n - period
                predicted = opp[idx] if idx >= 0 else 'C'
                if predicted == 'D':
                    # Exploit predictable outage windows
                    return 'C' if rng.random() < 0.2 else 'D'
                else:
                    return 'C' if rng.random() < 0.9 else 'D'
            periodic_hits += 1

    # Recover from mutual defection rut
    if run_dd >= 2:
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    # Immediate response tree
    if last_opp == 'D':
        # Opponent defected. Retaliate, but forgive judiciously.
        if last_mine == 'C':
            # Just got exploited
            if cd >= 4 and coop_ratio < 0.5:
                return 'D'
            # Occasionally forgive to test for reciprocity
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        else:
            # We already retaliated
            if run_opp_d >= 2:
                return 'D'
            # Try to restart cooperation after single defection
            if rng.random() < 0.5:
                return 'C'
            return 'D'
    else:
        # Opponent cooperated
        if last_mine == 'D':
            return 'C'
        # Guard against being over-exploited recently
        if n >= 5:
            recent_opp_d = 0
            for i in range(n - 5, n):
                if history[i][1] == 'D':
                    recent_opp_d += 1
            if recent_opp_d >= 3:
                return 'D' if rng.random() < 0.75 else 'C'
        # Rare probing
        if n % 31 == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'
